        return 1 + max(getHeight(root->left), getHeight(root->right));
    }
    void collect(TreeNode* root, int level, vector<int>& cur) {
        if (!root) return;
        if (level == 0) cur.push_back(root->val);
        else {
            collect(root->left, level - 1, cur);
            collect(root->right, level - 1, cur);
        }
    }
