        if (!root) return {};
        int h = getHeight(root);
        vector<vector<int>> res;
        for (int i = 0; i < h; ++i) {
            vector<int> cur;
            collect(root, i, cur);
            res.push_back(cur);
        }
        return res;
    }
};

