        if not root:
            return []
        def height(node):
            if not node:
                return 0
            return 1 + max(height(node.left), height(node.right))
        def collect(node, level, cur):
            if not node:
                return
            if level == 0:
                cur.append(node.val)
            else:
                collect(node.left, level - 1, cur)
                collect(node.right, level - 1, cur)
        h = height(root)
        res = []
        for i in range(h):
            cur = []
            collect(root, i, cur)
            res.append(cur)
        return res

